/** The source text of `free/filter-panel/products.tsx`, as the Usage tab shows it. */
export default '/**\n * Stackra file contract:\n * Purpose: the "products" demo of the native FilterPanel: a POS product catalogue with no saved views: category counts,\n *          an in-stock switch and a price range, the facets derived from the catalogue\'s columns.\n * Boundary: a demo with no props, @stackra/ui and local state only; the same file is the preview and the code shown.\n * Runtime: react-native\n * Governing contract: showcase redesign spec (2026-10-27) section 4 (demo contract); ADR 0302 (decisions 3 and 5);\n *          ADR 0505 (one filter model); ADR 0310 (decision 6).\n */\nimport type { CollectionColumn } from "@stackra/ui/contracts";\nimport { FilterPanel, useCatalogueText, useCollection } from "@stackra/ui/native";\n\nimport { MESSAGES } from "#src/constants/messages.constant";\nimport { FILTER_PANEL_DEMO_KEYS } from "#src/demos/free/filter-panel/filter-panel-demo-keys.constant";\n\n/** The demo\'s keys. */\nconst K = FILTER_PANEL_DEMO_KEYS.demo_free.filter_panel.products;\n\n/** Filter panel: Product catalogue. */\nexport default function Products() {\n  const t = useCatalogueText(MESSAGES.en);\n  const columns: readonly CollectionColumn[] = [\n    {\n      id: "category",\n      label: t(K.category),\n      type: "choice",\n      options: (["drinks", "food", "merch"] as const).map((id) => ({ id, label: t(K[id]) })),\n    },\n    { id: "in_stock", label: t(K.in_stock), type: "boolean" },\n    { id: "price", label: t(K.price), type: "number", min: 0 },\n  ];\n  // Server mode: the catalogue lives on the server, which answers the count; drinks are picked at the start.\n  const collection = useCollection({\n    columns,\n    mode: "server",\n    totalCount: 42,\n    initialState: {\n      filter: {\n        match: "all",\n        conditions: [\n          { id: "filter:category", field: "category", operator: "in", value: ["drinks"] },\n        ],\n      },\n    },\n  });\n  return (\n    <FilterPanel\n      label={t(K.label)}\n      collection={collection}\n      counts={{ category: { drinks: 42, food: 67, merch: 8 } }}\n    />\n  );\n}\n';
